import React, { useRef, useState, useEffect } from "react";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {
  const scannerRef = useRef(null);
  const beepRef = useRef(null);
  const isRunningRef = useRef(false); // ✅ track real scanner state

  const [isScanning, setIsScanning] = useState(false);
  const [student, setStudent] = useState(null);
  const [message, setMessage] = useState("");
  const [msgType, setMsgType] = useState("");
  const [history, setHistory] = useState([]);

  useEffect(() => {
    beepRef.current = new Audio(
      "https://www.soundjay.com/button/sounds/beep-01a.mp3"
    );

    return () => {
      // ✅ SAFE CLEANUP
      if (scannerRef.current && isRunningRef.current) {
        scannerRef.current
          .stop()
          .then(() => {
            scannerRef.current.clear();
            isRunningRef.current = false;
          })
          .catch(() => {});
      }
    };
  }, []);

  /* =============================
     START SCANNER
  ============================= */
  const startScanner = async () => {
    try {
      if (!scannerRef.current) {
        scannerRef.current = new Html5Qrcode("reader");
      }

      await scannerRef.current.start(
        { facingMode: "environment" },
        { fps: 20, qrbox: 250 },
        async (decodedText) => {
          await stopScanner(); // ✅ stop only once safely
          beepRef.current?.play().catch(() => {});
          handleScan(decodedText);
        }
      );

      isRunningRef.current = true; // ✅ mark running
      setIsScanning(true);
      setStudent(null);
      setMessage("");
      setMsgType("");
    } catch (err) {
      console.error("Camera error:", err);
      setMessage("❌ Camera access denied or not available.");
      setMsgType("error");
    }
  };

  /* =============================
     STOP SCANNER
  ============================= */
  const stopScanner = async () => {
    if (scannerRef.current && isRunningRef.current) {
      try {
        await scannerRef.current.stop();
        await scannerRef.current.clear(); // ✅ extra safe
      } catch (err) {
        console.log("Scanner already stopped");
      } finally {
        isRunningRef.current = false; // ✅ update state
        setIsScanning(false);
      }
    }
  };

  /* =============================
     HANDLE QR SCAN
  ============================= */
  const handleScan = async (qrData) => {
    try {
      const res = await fetch("http://localhost:5000/mark-attendance", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ qrData }),
      });

      const data = await res.json();
      const time = new Date().toLocaleTimeString();

      if (data.success) {
        setStudent(data.user);
        setMessage("✅ Attendance Marked Successfully!");
        setMsgType("success");

        setHistory((prev) => [
          { name: data.user?.name || "Unknown", time, status: "✅" },
          ...prev,
        ]);
      } else {
        if (data.user) setStudent(data.user);

        setMessage(data.message || "❌ Error marking attendance");
        setMsgType(data.message?.includes("already") ? "warning" : "error");

        setHistory((prev) => [
          { name: data.user?.name || "Unknown", time, status: "⚠️" },
          ...prev,
        ]);
      }
    } catch {
      setMessage("❌ Server Error. Make sure backend is running.");
      setMsgType("error");
    }
  };

  const msgColor =
    {
      success: "#16a34a",
      warning: "#d97706",
      error: "#dc2626",
    }[msgType] || "#fff";

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <h1 style={{ marginBottom: 6 }}>📷 QR Scanner</h1>
        <p style={{ color: "#9ca3af", fontSize: 13, marginBottom: 16 }}>
          Scan student ID card to mark attendance
        </p>

        {!isScanning ? (
          <button style={styles.startBtn} onClick={startScanner}>
            ▶ Start Scan
          </button>
        ) : (
          <button style={styles.stopBtn} onClick={stopScanner}>
            ■ Stop
          </button>
        )}

        <div
          id="reader"
          style={{
            width: "100%",
            marginTop: 16,
            borderRadius: 8,
            overflow: "hidden",
            border: isScanning ? "2px solid #00c6ff" : "none",
          }}
        />

        {message && (
          <div
            style={{
              marginTop: 14,
              padding: "10px 14px",
              borderRadius: 8,
              backgroundColor:
                msgType === "success"
                  ? "#dcfce7"
                  : msgType === "warning"
                  ? "#fef9c3"
                  : "#fee2e2",
              border: `1px solid ${msgColor}`,
              color: msgColor,
              fontWeight: "600",
              fontSize: 14,
            }}
          >
            {message}
          </div>
        )}

        {student && (
          <div style={styles.studentCard}>
            <div style={styles.avatar}>
              {student.name?.charAt(0).toUpperCase()}
            </div>
            <h2 style={{ margin: "8px 0 4px", fontSize: 18 }}>
              {student.name}
            </h2>
            <p style={{ color: "#9ca3af", fontSize: 13 }}>
              {student.college_name}
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

export default QRScanner;
